-- name: ListReportsFiltered :many
SELECT * FROM reports
WHERE (sqlc.narg('status')::text IS NULL OR status = sqlc.narg('status')::text)
  AND (sqlc.narg('state')::text IS NULL OR state = sqlc.narg('state')::text)
  AND (sqlc.narg('issue_type')::text IS NULL OR issue_type = sqlc.narg('issue_type')::text)
  AND (sqlc.narg('q')::text IS NULL OR title ILIKE '%' || sqlc.narg('q')::text || '%')
  AND (sqlc.arg('include_human_only')::boolean OR human_only = false)
ORDER BY sort_order ASC, created_at DESC
LIMIT sqlc.arg('lim')::int;

